\begin{theorem}[Derivative estimates---global]
\label{thm:chow-ii-appd-global-derivative-estimates}
\source{chow-et-al-ricci-flow-part-ii:page-0393,chow-et-al-ricci-flow-part-ii:page-0394}
\dcref{appD:D.23}
\group{Curvature Derivative Estimates}

If a closed Ricci flow satisfies $|\operatorname{Rm}|\leq K$ on
$[0,\alpha/K]\cap[0,T)$, then for each $m\in\mathbb N$,
\[
 |\nabla^m\operatorname{Rm}(x,t)|\leq
 \frac{C(m,n,\alpha)K}{t^{m/2}}
\]
on the same interval at positive times.
\end{theorem}

